import java.util.*;
public class Solution {
    public List<Integer> reverseKGroup(List<Integer> head, int k) {
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < head.size(); i += k) {
            int end = Math.min(i + k, head.size());
            List<Integer> sub = new ArrayList<>(head.subList(i, end));
            if (sub.size() == k) Collections.reverse(sub);
            res.addAll(sub);
        }
        return res;
    }
}

