#include <vector>
#include <algorithm>
using namespace std;
class Solution {
public:
    vector<int> reverseKGroup(vector<int>& head, int k) {
        vector<int> res;
        for (int i = 0; i < (int)head.size(); i += k) {
            int end = min(i + k, (int)head.size());
            vector<int> chunk(head.begin() + i, head.begin() + end);
            if ((int)chunk.size() == k) reverse(chunk.begin(), chunk.end());
            res.insert(res.end(), chunk.begin(), chunk.end());
        }
        return res;
    }
};
